const item = $input.first();
const body = (item && item.json && item.json.body) ? item.json.body : ((item && item.json) ? item.json : {});
const actionType = String(body.actionType || '').trim().toLowerCase();
const verifiedUserId = String(body.verifiedUserId || '').trim();
const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

if (!uuidRegex.test(verifiedUserId)) {
  return [{ json: { route: 'auth_required', actionType, verifiedUserId } }];
}

if (actionType === 'get_donations') {
  return [{ json: { route: 'get_donations', actionType, verifiedUserId } }];
}

if (actionType === 'create_donation') {
  let parsedPayload = {};
  if (typeof body.payload === 'string') {
    try {
      parsedPayload = JSON.parse(body.payload);
    } catch (e) {
      parsedPayload = { descripcion: body.payload };
    }
  } else if (body.payload && typeof body.payload === 'object') {
    parsedPayload = body.payload;
  } else {
    parsedPayload = body;
  }

  const descripcion = String(parsedPayload.descripcion || parsedPayload.description || parsedPayload.item || 'Donación solidaria').trim();
  const cantidadNum = Number(parsedPayload.cantidad ?? parsedPayload.quantity ?? 1);
  const cantidad = Number.isFinite(cantidadNum) && cantidadNum > 0 ? cantidadNum : 1;
  const unidadMedicion = String(parsedPayload.unidadMedicion || parsedPayload.unit || 'unidades').trim();
  const esUsado = Boolean(parsedPayload.esUsado ?? parsedPayload.isUsed ?? false);
  const nombreSubcategoria = String(parsedPayload.nombreSubcategoria || parsedPayload.category || parsedPayload.subcategoria || 'Alimentos').trim();
  const fechaVenc = parsedPayload.fechaVencimiento ? String(parsedPayload.fechaVencimiento).trim() : '';

  const bien = { descripcion, cantidad, unidadMedicion, esUsado, nombreSubcategoria };
  if (/^\d{4}-\d{2}-\d{2}$/.test(fechaVenc)) {
    bien.fechaVencimiento = fechaVenc;
  }

  const cargaBienesPayload = {
    idDonante: verifiedUserId,
    idAdministrador: 'a2222222-2222-4222-8222-222222222222',
    bienesBrutos: [bien]
  };
  return [{ json: { route: 'create_donation', actionType, verifiedUserId, cargaBienesPayload, resumenBien: `${cantidad} ${unidadMedicion} de ${descripcion} (${nombreSubcategoria})` } }];
}

return [{ json: { route: 'unknown', actionType, verifiedUserId } }];

const items = $input.all().map(i => i.json).filter(Boolean);
let list = [];
if (items.length === 1 && Array.isArray(items[0])) {
  list = items[0];
} else if (items.length === 1 && items[0].error) {
  return [{ json: { status: 'ok', result: 'No pude consultar tus donaciones en este momento porque el servicio respondió con error. Intentá nuevamente en unos minutos.' } }];
} else {
  list = items.filter(d => d && (d.id || d.codigoCorto));
}
if (list.length === 0) {
  return [{ json: { status: 'ok', result: 'No tenés donaciones registradas todavía en DonaTrack.' } }];
}
list.sort((a, b) => String(b.fechaCreacion || '').localeCompare(String(a.fechaCreacion || '')));
const top5 = list.slice(0, 5);
const lines = top5.map((d, idx) => {
  const codigo = d.codigoCorto || ('#DT-' + String(d.id || '').slice(0, 4).toUpperCase());
  const desc = d.descripcion || d.subcategoria || 'Donación solidaria';
  const estado = d.estado || 'EN_DEPOSITO';
  const fecha = d.fechaCreacion ? String(d.fechaCreacion).slice(0, 10) : '';
  const destino = d.correoBeneficiario ? ` | Destino: ${d.correoBeneficiario}` : '';
  return `${idx + 1}. ${codigo} - ${desc} | Estado: ${estado} | Fecha: ${fecha}${destino}`;
});
const resultText = `Encontré ${list.length} donación(es). Últimas ${top5.length}:\n` + lines.join('\n');
return [{ json: { status: 'ok', result: resultText } }];

const resp = $input.first()?.json || {};
const req = $('Normalizar Tool Request').first()?.json || {};
if (resp.error) {
  return [{ json: { ok: false, errorMsg: typeof resp.error === 'string' ? resp.error : JSON.stringify(resp.error), resumenBien: req.resumenBien } }];
}
let donacionId = resp.id || '';
if (Array.isArray(resp.donacionesSegmentadas) && resp.donacionesSegmentadas.length > 0 && resp.donacionesSegmentadas[0].id) {
  donacionId = resp.donacionesSegmentadas[0].id;
}
const codigoCorto = donacionId ? ('#DT-' + String(donacionId).slice(0, 4).toUpperCase()) : '#DT-NUEVA';
return [{ json: { ok: Boolean(donacionId), donacionId: String(donacionId || ''), codigoCorto, resumenBien: req.resumenBien } }];

const info = $('Extraer ID Donacion').first()?.json || {};
if (!info.ok || !info.donacionId) {
  return [{ json: { status: 'ok', result: 'No se pudo registrar la donación en el sistema. Verificá los datos (descripción, cantidad y subcategoría) e intentá nuevamente.' } }];
}
return [{ json: { status: 'ok', result: `Donación registrada con éxito bajo el código ${info.codigoCorto} (${info.resumenBien}). Estado actual: EN_DEPOSITO (+10 pts en Incentivos).` } }];

const item = $input.first();
const body = (item && item.json && item.json.body) ? item.json.body : ((item && item.json) ? item.json : {});
const message = String(body.message || body.mensaje || '').trim();
const sessionId = String(body.sessionId || ('anon-' + Date.now())).trim();
const verifiedUserId = body.verifiedUserId ? String(body.verifiedUserId).trim() : null;
const verifiedEmail = body.verifiedEmail ? String(body.verifiedEmail).trim() : null;
const action = body.action ? String(body.action).trim().toUpperCase() : null;
return [{ json: { message, sessionId, verifiedUserId, verifiedEmail, action } }];

const input = $('Normalizar Entrada').first().json;
const mongoItem = $input.first()?.json || {};
const hasValidMongo = Boolean(mongoItem && !mongoItem.error && mongoItem.sessionId);
const hasActiveSfSession = Boolean(hasValidMongo && mongoItem.sfSessionId && mongoItem.active !== false);

if (hasActiveSfSession || input.action === 'HANDOFF_AGENT') {
  const needsNewSfSession = !hasActiveSfSession;
  const sfSessionId = needsNewSfSession ? '' : String(mongoItem.sfSessionId);
  const nextSequenceId = needsNewSfSession ? 1 : ((Number(mongoItem.sequenceId) || 0) + 1);
  let messageToSend = input.message;
  if (input.action === 'HANDOFF_AGENT' && !messageToSend) {
    messageToSend = (hasValidMongo && mongoItem.lastUnansweredMessage) ? String(mongoItem.lastUnansweredMessage) : 'Hola, necesito ayuda de soporte';
  }
  if (!messageToSend) {
    messageToSend = 'Hola, necesito ayuda de soporte';
  }
  return [{
    json: {
      route: 'agent',
      sessionId: input.sessionId,
      verifiedUserId: input.verifiedUserId,
      verifiedEmail: input.verifiedEmail,
      needsNewSfSession,
      sfSessionId,
      nextSequenceId,
      messageToSend
    }
  }];
}

const norm = input.message.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();
const requiresAgent = /\b(mis donaciones|mi donacion|crear donacion|nueva donacion|hacer una donacion|reclamo|problema|error|agente|humano|sofia|soporte|ayuda personal)\b/.test(norm);

let faqChunks = null;
if (!requiresAgent) {
  if (norm === '¿como dono?' || norm === '¿como donar?' || /\b(como (?:puedo )?(?:donar|dono)|pasos para donar|quiero donar)\b/.test(norm)) {
    faqChunks = [
      'Donar en DonaTrack es muy simple y sigue 3 pasos:',
      '- **1) Registrate** gratis como Donante.\n- **2) Cargá tu donación** detallando artículos, cantidades y estado.\n- **3) Seguí cada etapa** desde el punto de recepción hasta la entrega auditada con remito en el comedor.'
    ];
  } else if (/\b(verificar ong|sumar mi organizacion|ong|comedor|merendero)\b/.test(norm)) {
    faqChunks = [
      'En **DonaTrack** auditamos cada comedor u organización beneficiaria antes de asignarle donaciones.',
      'Podés postular tu entidad desde el botón **Sumar mi Organización** ingresando CUIT, dirección real y necesidades prioritarias para validación del equipo.'
    ];
  } else if (/\b(rastrear|rastreo|remito|seguimiento|codigo)\b/.test(norm)) {
    faqChunks = [
      'Cada donación recibe un código único tipo `#DT-XXXX` cuando ingresa a depósito.',
      'Desde el panel público o tu portal de Donante podés seguir en el mapa el estado **En Depósito → Asignada / En Ruta → Entregada con Remito**.'
    ];
  } else if (/\b(campana|campanas)\b/.test(norm)) {
    faqChunks = [
      'Podés explorar las organizaciones y necesidades activas directamente desde la sección de campañas o en tu portal de Donante.'
    ];
  } else if (/\b(registrar|registro|cuenta nueva)\b/.test(norm)) {
    faqChunks = [
      'El registro en DonaTrack es **100% gratuito** tanto para Donantes como para Organizaciones Beneficiarias desde `/registro`.'
    ];
  } else if (/\b(que tipo|aceptan|que puedo donar|elementos)\b/.test(norm)) {
    faqChunks = [
      'Podés donar:\n- Alimentos no perecederos\n- Ropa y calzado en buen estado\n- Juguetes, útiles escolares y mobiliario comunitario.'
    ];
  } else if (/\b(voluntario|logistica|camion)\b/.test(norm)) {
    faqChunks = [
      'Podés colaborar sumando tu organización como centro de recepción o coordinando entregas logísticas con nuestro equipo administrativo.'
    ];
  } else if (/\b(horario|horarios|sede|sedes|puntos? de entrega|puntos? de recepcion|donde llevar|donde entrego)\b/.test(norm)) {
    faqChunks = [
      'Los horarios y puntos de recepción están disponibles en la sección **Mapa de Impacto** de la página principal y se coordinan según el nodo elegido.'
    ];
  } else if (/^(hola|buenas|buen dia|buenas tardes|buenas noches|ayuda|menu|opciones)[!?.]*$/.test(norm)) {
    faqChunks = [
      '¡Hola! Soy el asistente rápido de **DonaTrack**. Elegí una de las opciones rápidas o preguntame lo que necesites.'
    ];
  }
}

if (faqChunks) {
  return [{
    json: {
      route: 'bot_faq',
      responseBody: {
        mode: 'bot',
        chunks: faqChunks,
        respuesta: faqChunks.join('\n\n')
      }
    }
  }];
}

const fallbackMsg = 'No tengo esa info a mano desde acá, pero puedo pasarte con alguien del equipo.';
return [{
  json: {
    route: 'bot_fallback',
    sessionId: input.sessionId,
    lastUnansweredMessage: input.message || 'Consulta general de soporte',
    verifiedUserId: input.verifiedUserId,
    verifiedEmail: input.verifiedEmail,
    active: false,
    updatedAt: new Date().toISOString(),
    responseBody: {
      mode: 'bot',
      chunks: [fallbackMsg],
      respuesta: fallbackMsg,
      suggestedAction: {
        type: 'HANDOFF_AGENT',
        label: 'Contactar con un agente'
      }
    }
  }
}];

const ctx = $('Evaluar Nivel Chat').first().json;
const tokenData = $('OAuth Salesforce').first().json;
const rawOrg = String($env.SF_MY_DOMAIN_URL || $env.ORG_URL || tokenData.instance_url || '').replace(/^https?:\/\//i, '').replace(/\/+$/, '');
const sessionBody = {
  externalSessionKey: ctx.sessionId,
  instanceConfig: { endpoint: 'https://' + rawOrg },
  streamingCapabilities: { chunkTypes: ['Text'] },
  bypassUser: true,
  variables: [
    { name: '$Context.EndUserLanguage', type: 'Text', value: 'es_AR' },
    { name: 'Verified_User_Id', type: 'Text', value: String(ctx.verifiedUserId || '') },
    { name: 'Verified_User_Email', type: 'Text', value: String(ctx.verifiedEmail || '') }
  ]
};
return [{ json: { accessToken: tokenData.access_token, sfSessionBody: sessionBody } }];

const resp = $input.first()?.json || {};
const ctx = $('Evaluar Nivel Chat').first().json;
