const sfResp = $input.first()?.json || {};
const ctx = $('Evaluar Nivel Chat').first().json;
let prep = { sfSessionId: ctx.sfSessionId, sequenceId: ctx.nextSequenceId };
try {
  if (ctx.needsNewSfSession) {
    prep = $('Preparar Mensaje Inicial SF').first().json;
  } else {
    prep = $('Preparar Mensaje Siguiente SF').first().json;
  }
} catch (e) {}

const cleanText = (raw) => {
  if (!raw) return '';
  return String(raw)
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/(p|div|h[1-6]|li|tr)>/gi, '\n')
    .replace(/<li[^>]*>/gi, '- ')
    .replace(/<[^>]*>/g, '')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/\n{3,}/g, '\n\n')
    .trim();
};

let rawTexts = [];
if (Array.isArray(sfResp.messages)) {
  rawTexts = sfResp.messages.map(m => cleanText(m.message || m.text || '')).filter(Boolean);
}
if (rawTexts.length === 0 && sfResp.message) {
  const single = cleanText(sfResp.message);
  if (single) rawTexts = [single];
}
if (!prep.sfSessionId) {
  rawTexts = ['Sofía está momentáneamente desconectada de Salesforce Agentforce. Podés seguir usando las preguntas rápidas mientras se completa la configuración del agente.'];
} else if (rawTexts.length === 0) {
  rawTexts = ['No recibí respuesta del agente en este momento. ¿Podés repetir tu consulta?'];
}

const chunks = [];
for (const txt of rawTexts) {
  const parts = txt.split(/\n\n+|(?<=[.!?])\s+(?=[A-ZÁÉÍÓÚÑ¿¡\d])/).map(s => s.trim()).filter(Boolean);
  for (const p of parts) chunks.push(p);
}
if (chunks.length === 0) chunks.push('¿En qué más te puedo ayudar?');

return [{
  json: {
    sessionId: ctx.sessionId,
    sfSessionId: prep.sfSessionId || '',
    sequenceId: prep.sequenceId || 1,
    verifiedUserId: ctx.verifiedUserId,
    verifiedEmail: ctx.verifiedEmail,
    active: Boolean(prep.sfSessionId),
    updatedAt: new Date().toISOString(),
    responseBody: {
      mode: 'agent',
      agentName: 'Sofía - Soporte Donatrack',
      chunks,
      respuesta: chunks.join('\n\n')
    }
  }
}];
